contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        require(true);

        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(minSum == v);
    }

    receive() external payable {}
}

