pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v) internal {
        vm.assume(true);
        try c.SetMinSum(v) {} catch { return; }
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        assertTrue(minSum == v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
